mapper.select:
deleted = 0 and id = #{id}
and (guardian_phone is null or guardian_phone = '' or allergy is null or allergy = '' or birthday is null or guardian_name is null or guardian_name = '' or address is null or address = '' or clazz_id is null or enroll_date is null)
and name like concat('%', #{name}, '%') and gender = #{gender} and birthday = #{birthday} and clazz_id = #{clazzId} and guardian_name like concat('%', #{guardianName}, '%') and guardian_phone like concat('%', #{guardianPhone}, '%') and address like concat('%', #{address}, '%') and allergy like concat('%', #{allergy}, '%') and enroll_date = #{enrollDate}
and (case when enroll_date is not null then (case when enroll_date > curdate() then 0 else 1 end) else status end) = #{status}
order by id desc

select count(*) from child
where deleted = 0 and clazz_id = #{clazzId}
  and (case when enroll_date is not null
            then (case when enroll_date > curdate() then 0 else 1 end)
            else status end) = 1
 and id != #{excludeChildId}
